local _, ns = ...
if ns.LOCALE ~= "esES" and ns.LOCALE ~= "esMX" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/esES.lua.
L["WN56_1_TITLE"] = "Tema personalizado más rápido"
L["WN56_1_TEXT"] = "Cambiar de aspecto o una parte de Con tema ya no detiene el juego, y una parte desmarcada recupera los colores propios del juego. Tema personalizado está desactivado por defecto; actívalo en las opciones (/fcui), en Aspecto."
L["WN55_1_TITLE"] = "Textura de barra"
L["WN55_1_TEXT"] = "Una opción de Textura de barra en Marcos de unidad para las barras de salud y maná: Clásica, ahora más suave, Marcos de banda, Sólida o Barra de habilidad."
L["WN55_2_TITLE"] = "Botón de la tienda"
L["WN55_2_TEXT"] = "El botón de la tienda puede estar en el micromenú de la 1.x con un marco propio. Está oculto por defecto: para mostrarlo, desmarca Tienda en Ocultar microbotones, en la página Barras de acción de las opciones (/fcui)."
L["WN55_3_TITLE"] = "Botón del libro de hechizos"
L["WN55_3_TEXT"] = "El botón del libro de hechizos del micromenú se queda pulsado mientras el libro muestra tus hechizos."
L["WN55_4_TITLE"] = "Correcciones"
L["WN55_4_TEXT"] = "El consejo del botón social dice Social, y un título de ventana largo conserva los extremos de su placa de título."
L["WN54_1_TITLE"] = "Opciones más fluidas"
L["WN54_1_TEXT"] = "Cambiar una opción ya no da tirones: solo se vuelven a colocar las partes de la interfaz a las que afecta esa opción."
L["WN54_2_TITLE"] = "Micromenú"
L["WN54_2_TEXT"] = "Los microbotones que ocultas siguen ocultos, un botón que queda solo en la fila se coloca al final, y la fila queda centrada en la barra sin huecos en su suelo."
L["WN54_3_TITLE"] = "Minimapa en instancias"
L["WN54_3_TEXT"] = "Con Rotar minimapa activado, las instancias ya no muestran un segundo anillo grande alrededor del minimapa."
L["WN54_4_TITLE"] = "Botón de vivienda"
L["WN54_4_TEXT"] = "El botón de vivienda del micromenú tiene un marco 1.x como los demás."
L["WN54_5_TITLE"] = "Correcciones"
L["WN54_5_TEXT"] = "Tras recargar en combate, el marco propio del juego de la barra de experiencia ya no aparece sobre la barra 1.x, y un tamaño de ventana guardado en el modo edición ya no puede sacar una ventana de la pantalla, como un mapa del mundo grande."
L["WN53_1_TITLE"] = "Partes del tema más finas"
L["WN53_1_TEXT"] = "En Tema personalizado, la lista Con tema se divide en partes más finas, como las barras de lanzamiento, las placas de nombre, el micromenú y los menús, para que puedas dejar cualquiera con el aspecto clásico. Tema personalizado está desactivado por defecto; actívalo en las opciones (/fcui), en Aspecto."
L["WN53_2_TITLE"] = "Barras de acción derechas"
L["WN53_2_TEXT"] = "Con Barra clásica desactivada y el minimapa agrandado en el modo edición, las barras de acción 4 y 5 de la derecha ya no se reducen a unos dos tercios; solo se reducen lo que pide el espacio bajo el minimapa."
L["WN53_3_TITLE"] = "Color personalizado"
L["WN53_3_TEXT"] = "Hacer clic fuera del selector de color conserva el color elegido; Cancelar o Escape aún lo deshacen."
L["WN53_4_TITLE"] = "Arreglos del tema"
L["WN53_4_TEXT"] = "Cuando el tema colorea las ventanas del juego, ya no destellan con sus propios colores al abrirse, y los botones rojos del menú del juego muestran bien sus extremos. Los marcos de otros addons conservan su propio aspecto; para colorearlos también, activa Otros addons en la lista Con tema, en las opciones (/fcui), en Aspecto."
L["WN52_1_TITLE"] = "Insignia de honor"
L["WN52_1_TEXT"] = "Los marcos del jugador, del objetivo y de foco pueden mostrar la insignia de nivel de honor del juego en lugar del emblema de facción de la 1.x. Desactivado por defecto; actívalo en las opciones (/fcui), en Marcos de unidad."
L["WN52_2_TITLE"] = "Pestañas del chat al pasar el ratón"
L["WN52_2_TEXT"] = "Con las pestañas del chat al pasar el ratón, solo se muestran las pestañas de la ventana de chat bajo el ratón: las de las ventanas acopladas juntas, o la de una ventana que sacaste por separado."
L["WN52_3_TITLE"] = "Ojo del buscador de grupos"
L["WN52_3_TEXT"] = "Ajustar al minimapa del ojo del buscador de grupos ya no está en las opciones; sigue en los ajustes del ojo en el modo edición."
L["WN52_4_TITLE"] = "Ojo del buscador de grupos"
L["WN52_4_TEXT"] = "Ajustar al minimapa del ojo del buscador de grupos pasó de las opciones a su cuadro Buscador de grupos en Ventanas de ClassicUI Forever (modo edición), en Minimapa. El cuadro sigue ahí mientras el ojo está fuera del borde, para que puedas volver a activarlo."
L["WN52_5_TITLE"] = "Ayuda de Destello de daño"
L["WN52_5_TEXT"] = "La ayuda de Destello de daño dice que el rojo aparece en la barra de salud del marco del jugador. Destello de daño está desactivado por defecto; actívalo en las opciones (/fcui), en Marcos de unidad."
L["WN51_1_TITLE"] = "Maestría y versatilidad"
L["WN51_1_TEXT"] = "Las estadísticas de la ventana de personaje muestran Maestría y Versatilidad, en General."
L["WN51_2_TITLE"] = "Ventana de profesiones"
L["WN51_2_TEXT"] = "La elección de expansión está ahora en el menú Filtro. La ventana se abre donde están las demás ventanas del juego, sin hueco tras el libro de hechizos, y su borde inferior pasa bajo los botones Crear."
L["WN51_3_TITLE"] = "Opciones de Una bolsa"
L["WN51_3_TEXT"] = "Las opciones bajo Una bolsa solo cambian las ventanas de bolsa del addon, así que se ven en gris mientras Ventanas de bolsa está desactivado. Para usarlas, actívalo en las opciones (/fcui), en Bolsas."
L["WN51_4_TITLE"] = "Pestañas"
L["WN51_4_TEXT"] = "En las ventanas de profesiones y de talentos, la pestaña elegida muestra su cara entera y las demás pestañas ya no muestran una franja negra."
L["WN50_1_TITLE"] = "Color con textura"
L["WN50_1_TEXT"] = "Color con textura, que mantiene la textura del arte en el color del tema, ahora colorea ventanas enteras, no solo su metal: la piedra de bolsas y pestañas, los bordes de las cajas de búsqueda y de texto, y las flechas de página del libro de hechizos, donde una flecha usable es más clara que una agotada. Desactivado por defecto; actívalo en las opciones (/fcui), en Aspecto."
L["WN50_2_TITLE"] = "Temas en las ventanas del juego"
L["WN50_2_TEXT"] = "Los temas también colorean el arte propio del juego que queda en las ventanas que el addon rediseña: las pestañas de la ventana social, las barras de desplazamiento, las cajas de búsqueda, los desplegables como el de estado, la caja de dinero, las cabeceras de columna de la lista de hermandad, la caja de chat de las comunidades y la pestaña de banda."
L["WN50_3_TITLE"] = "Bronce en retail"
L["WN50_3_TEXT"] = "El tema Bronce ahora también colorea el arte propio de las ventanas del juego, que es plateado en retail, como hacen los demás temas."
L["WN50_4_TITLE"] = "Ocultar botones de ayuda"
L["WN50_4_TEXT"] = "Oculta los botones de ayuda del juego, la i arriba a la izquierda de ventanas como el mapa, las profesiones y el libro de hechizos, y los consejos de tutorial que abren. Activado por defecto; desactívalo en las opciones (/fcui), en Otros."
L["WN50_5_TITLE"] = "Ocultar pestaña lateral Quién"
L["WN50_5_TEXT"] = "El buscador de grupos puede quitar su pestaña lateral Quién, así Quién solo se abre desde la ventana social. Activado en instalaciones nuevas; si ya usabas el addon, actívalo en las opciones (/fcui), en Social."
L["WN50_6_TITLE"] = "Correcciones"
L["WN50_6_TEXT"] = "El anillo del retrato del libro de hechizos toma el tema Bronce en vez de quedarse plateado, y una flecha de página que puede volver a pasar ya no conserva su color agotado hasta que haces clic en otro sitio. Las placas de nombre muestran la calavera para unidades amistosas de nivel desconocido, como el marco de objetivo. El borde interior de las pestañas Amigos y Banda de la ventana social toma el color del tema, y se corrigió un error que el tema podía causar en combate."
L["WN49_1_TITLE"] = "Más pequeño y ligero"
L["WN49_1_TEXT"] = "La descarga ocupa menos de la mitad que antes y el addon usa menos memoria. Los temas ahora colorean el arte propio del juego en vez de incluir copias de él, y una pieza con tema solo se crea la primera vez que se muestra. Los temas se ven igual."
L["WN49_2_TITLE"] = "Ocultar texto de zona"
L["WN49_2_TEXT"] = "Oculta los nombres de zona y subzona que aparecen en pantalla al entrar en un área. Desactivado por defecto; actívalo en las opciones (/fcui), en Otros."
L["WN49_3_TITLE"] = "Libro de hechizos y barras"
L["WN49_3_TEXT"] = "Mientras el libro de hechizos está abierto, las barras laterales muestran sus huecos vacíos, como en Era, así que un hechizo puede ir directamente a una de ellas, también en combate."
L["WN49_4_TITLE"] = "Pestañas de la ventana del personaje"
L["WN49_4_TEXT"] = "Las pestañas de la ventana del personaje son las propias de Era, como en Forever: con el tamaño de sus nombres y la pestaña elegida abierta hacia la página."
L["WN49_5_TITLE"] = "Páginas de opciones"
L["WN49_5_TEXT"] = "Las páginas de la ventana de opciones se agrupan por tipo: primero Aspecto, luego las partes en pantalla, las páginas del minimapa y del mapa una junto a la otra, después las ventanas del juego, y Otros al final."
L["WN49_6_TITLE"] = "Correcciones"
L["WN49_6_TEXT"] = "Las listas de estadísticas y de equipo de la ventana del personaje vuelven a mostrar sus flechas de desplazamiento. El retrato del libro de hechizos llena su anillo como en Era, el del libro de profesiones coincide con él y ya no crece al abrirse, y el icono de la ventana de colecciones ya no se ve demasiado ampliado. La rueda del ratón acerca y aleja la vista previa de Apariencias, y el gestor de banda plegado ya no muestra una línea de más."
L["WN48_1_TITLE"] = "Mapa y registro de misiones juntos"
L["WN48_1_TEXT"] = "La lista de misiones junto al mapa, con el texto y las recompensas de la misión elegida en dos páginas debajo, como el mapa de Wrath. Arrastra la esquina del mapa para darle tamaño y el divisor para ensanchar la lista. Desactivado por defecto; actívalo con Mapa y misiones clásicos combinados en las opciones (/fcui), en Mapa, con la Barra de navegación: estilo Classic."
L["WN48_2_TITLE"] = "Texto de la lista de misiones"
L["WN48_2_TEXT"] = "Tamaño de letra de la lista de misiones y Tamaño de letra del texto de la misión agrandan las listas y el texto de misiones del mapa, y Lista sobre el pergamino del juego pone la lista en la página del registro de misiones del juego en vez de piedra oscura. Empiezan con el aspecto del juego; actívalos en las opciones (/fcui), en Mapa."
L["WN48_3_TITLE"] = "Hermandad como en Era"
L["WN48_3_TEXT"] = "La pestaña de hermandad sigue el diseño de Classic Era: los encabezados de columna, la barra sobre el mensaje del día, los totales, los botones y la casilla de mostrar miembros desconectados están donde los tiene Era, y los nombres de clase se ven en blanco."
L["WN48_4_TITLE"] = "Banco como en Era"
L["WN48_4_TEXT"] = "El banco conserva la cuadrícula más grande de Forever y toma debajo el diseño de Era: una fila de huecos de bolsa a tamaño completo, la línea de compra y tu dinero en una franja a lo largo de la parte inferior."
L["WN48_5_TITLE"] = "Territorio en nombres de zona"
L["WN48_5_TEXT"] = "El territorio de una zona, como Territorio de la Alianza, se muestra también fuera de las capitales, como en 1.x. Para conservar los nombres del juego, desmarca Territorio en nombres de zona en las opciones (/fcui), en Otros."
L["WN48_6_TITLE"] = "Posiciones del diseño clásico"
L["WN48_6_TEXT"] = "El botón Diseño clásico y la configuración del primer inicio de sesión ponen tus marcos de jugador, objetivo y foco y las barras 4 y 5 donde los tiene Classic Era. Nada se mueve solo: pulsa Diseño clásico en la ventana de opciones para usarlas."
L["WN48_7_TITLE"] = "Barra inferior"
L["WN48_7_TEXT"] = "El botón del Mapa del mundo va después del botón social, como en Era, y el arte del micromenú es el de Era, más oscuro hacia su extremo derecho, con la ventana de latencia, el llavero y las bolsas a su lado donde los tiene Era."
L["WN48_8_TITLE"] = "Opciones menores"
L["WN48_8_TEXT"] = "La ventana \"Has recibido\" del juego para un botín raro, una tirada ganada o una mejora se oculta, ya que 1.x no la tenía; Aviso de botín la recupera. Ocultar la búsqueda de bolsas y Ocultar el botón de ordenar quitan esos elementos de las bolsas. Los tres están desactivados por defecto; actívalos en las opciones (/fcui), en Otros y Bolsas. Las coordenadas del mapa en Mapa son ajustes propios del juego."
L["WN48_9_TITLE"] = "En retail"
L["WN48_9_TEXT"] = "El ojo del buscador de grupo se mueve alrededor del minimapa y tiene tamaño en las opciones del minimapa de nuestro modo de edición, crítico y celeridad muestran los tooltips del juego, y Ocultar el botón de ayuda del mapa oculta su botón de tutorial. Está desactivado por defecto; actívalo en las opciones (/fcui), en Mapa."
L["WN48_10_TITLE"] = "Correcciones"
L["WN48_10_TEXT"] = "El brillo de perjuicios del grupo es un anillo alrededor del retrato, una página saqueada vacía pasa a la siguiente, el ojo del buscador de grupo crece con el minimapa y ya no da errores ni desaparece en el modo de edición, el menú de columna de la lista Quién elige y ordena una columna directamente, y las páginas de misión completan las recompensas que llegan tarde. Inspeccionar talentos en combate muestra solo nuestra ventana, y un combate que empieza a mitad de arrastre deja la ventana donde está."
L["WN47_1_TITLE"] = "Hermandad y comunidades"
L["WN47_1_TEXT"] = "La ventana de Hermandad y comunidades es ahora una página social: lleva las pestañas Amigos, Quién, Hermandad y Banda en sus dos modos, y el modo pequeño tiene el tamaño de la ventana social, con el anillo y el retrato."
L["WN47_2_TITLE"] = "Perfiles como texto"
L["WN47_2_TEXT"] = "Exportar e Importar en la página de perfiles: un perfil como una línea de texto para copiarlo a otra cuenta o a un amigo, y de vuelta a un perfil nuevo."
L["WN47_3_TITLE"] = "Anchura del menú"
L["WN47_3_TEXT"] = "El diálogo de edición del micromenú tiene un control Anchura del menú junto a Tamaño: la fila se ensancha o estrecha y los botones conservan su tamaño. Tamaño por encima del 100 % ahora ensancha el arte con la fila."
L["WN47_4_TITLE"] = "Ventana social"
L["WN47_4_TEXT"] = "La ventana social se queda en su sitio tras una búsqueda de Quién, el botón de estado bajo el título acepta clics, los botones del micromenú ocultos ya no abren sus ventanas desde un hueco vacío."
L["WN47_5_TITLE"] = "Mapa en combate"
L["WN47_5_TEXT"] = "El mapa del mundo solo está protegido en combate mientras el mapa clásico de este addon lo coloca, así que los addons de mapa funcionan en combate con el mapa clásico desactivado."
L["WN46_1_TITLE"] = "Ventana social"
L["WN46_1_TEXT"] = "La pestaña Banda vuelve a la fila de pestañas de la ventana social en los clientes que tienen desactivado el nuevo sistema social del juego, y la pestaña pequeña bajo Aliados recientes vuelve a decir Unión rápida en vez de Banda. La ventana ahora solo se arrastra por su barra de título, así que el botón de estado bajo el título vuelve a aceptar clics."
L["WN45_1_TITLE"] = "Colecciones en Retail"
L["WN45_1_TEXT"] = "La ventana clásica de colecciones también está en Retail: monturas, mascotas con tu equipo de combate al lado, juguetes y reliquias como páginas de libro, campamentos y apariencias, cada página con los filtros del juego. Arrastra una vista previa para girarla, usa la rueda sobre una criatura para acercarla, arrastra una apariencia con el botón derecho para moverla; el botón junto a las flechas la restablece. Ventana de colecciones está activada por defecto, en las opciones (/fcui) bajo Personaje, hechizos, talentos."
L["WN45_2_TITLE"] = "Una búsqueda en cada página"
L["WN45_2_TEXT"] = "Cada página de opciones tiene su propio cuadro de búsqueda arriba a la derecha, que solo busca en esa página; la búsqueda de arriba a la izquierda sigue cubriendo todas las páginas. Desactivar todo y Opciones por defecto pasaron a la parte inferior derecha. Ventanas de estilo clásico desapareció de Todas las ventanas: ahora cada ventana es su propia casilla y ninguna fila se atenúa por otra."
L["WN45_3_TITLE"] = "Búsqueda de estadísticas"
L["WN45_3_TEXT"] = "Un cuadro de búsqueda en la pestaña Estadísticas de la ventana del personaje encuentra estadísticas por nombre o categoría. Desactivada por defecto; actívala en las opciones (/fcui), bajo Personaje, hechizos, talentos."
L["WN45_4_TITLE"] = "Tamaño de la interfaz"
L["WN45_4_TEXT"] = "El diseño clásico pone la escala de la interfaz del juego al tamaño de Classic Era, 90% en la mayoría de pantallas. Desactivar todo, en la barra lateral de las opciones, ahora ofrece devolver tu tamaño anterior con una casilla en su confirmación, y Opciones por defecto ofrece el tamaño de Era mientras tengas otro. Ambas confirmaciones aconsejan guardar antes un perfil para volver a tu configuración, y la página de Preguntas explica el tamaño."
L["WN45_5_TITLE"] = "Lista Quién desactivada"
L["WN45_5_TEXT"] = "Con Lista Quién desactivada, la pestaña Quién de la ventana social y la pestaña lateral Quién del buscador de grupos abren la lista Quién propia de Forever, una página del buscador; Anuncio y Explorar vuelven a las páginas clásicas. Ocultar pestaña Quién quita la pestaña del pie de la ventana social. Desactivada por defecto; actívala en las opciones (/fcui), bajo Social."
L["WN45_6_TITLE"] = "Bolsas y barras"
L["WN45_6_TEXT"] = "Ocultar el arte del llavero quita el arte del llavero de la barra. Desactivada por defecto; actívala en las opciones (/fcui), bajo Bolsas. En Retail la bolsa de reactivos tiene sus propias opciones bajo Bolsas: como arte de llave, como arte de bolsa comprimida, una ranura completa u oculta. Una barra ya no activa nada más y lista sus parejas debajo, y las flechas de página modernas se sitúan sobre el grifo con Grifos sobre las barras."
L["WN45_7_TITLE"] = "Correcciones"
L["WN45_7_TEXT"] = "En Retail, un druida en forma de lechúcico veía dos barras de maná; ahora solo se ve la nuestra, bajo el poder astral. La página Profesiones del libro de hechizos vuelve a su sitio cuando se cierra otra ventana, y en Retail la ventana de fabricación se abre junto al libro de hechizos, no encima, con su borde bajo la fila Crear; su botón de ampliar desapareció, ya que la página del juego se abre desde la receta. El ojo del buscador de grupos se queda en el borde del minimapa en el modo de edición, y en Retail arrastrar con Mayús lo desliza por el borde. La casilla del micromenú en el modo de edición ya no parpadea en la esquina, el aviso de un botón del micromenú pulsa con el brillo de 1.x, los nombres amistosos ya no parpadean en morado en Retail, una vista previa de colecciones se abre encuadrada, Desactivar todo desmarca también las ventanas bajo una casilla superior, Tiradas de botín está activada por defecto en instalaciones nuevas, y la búsqueda de opciones mantiene brillantes las filas sobre una coincidencia."
L["WN44_1_TITLE"] = "Temas en un color"
L["WN44_1_TEXT"] = "Los temas ahora dibujan todo en un solo color uniforme por defecto, como un modo oscuro. Para devolver las texturas a las partes que elijas, activa Color con textura en las opciones (/fcui), en Aspecto; Con tema elige qué partes toman el tema. El pergamino también toma el tema, con texto claro sobre una página oscura. Si ya usabas un tema, tu aspecto se conserva."
L["WN44_2_TITLE"] = "Monedas clásicas"
L["WN44_2_TEXT"] = "El oro, la plata y el cobre muestran las monedas redondas de Era en tus bolsas, en los vendedores, en el correo, las misiones y las descripciones. Desmarca Monedas clásicas en las opciones (/fcui), en Aspecto, para las modernas."
L["WN44_3_TITLE"] = "Una barra"
L["WN44_3_TEXT"] = "Una barra ahora también oculta la barra de latencia y pone el llavero con las bolsas mediante sus propias opciones, así que ambos pueden volver. Flechas de página modernas muestra las flechas pequeñas de página del juego sobre el grifo izquierdo; está desactivada por defecto, actívala en las opciones, en Una barra."
L["WN44_4_TITLE"] = "Bolsas"
L["WN44_4_TEXT"] = "Ocultar bordes de calidad y Ocultar moneda de chatarra quitan a tus objetos los bordes de color de su calidad y la moneda de oro del vendedor. Ambas están desactivadas por defecto; actívalas en las opciones, en Bolsas."
L["WN44_5_TITLE"] = "Minimapa"
L["WN44_5_TEXT"] = "Ocultar bordes de botones tiene un desplegable Botones para elegir qué botones pierden su anillo, el botón de minimapa de cada accesorio puede tener su propia elección, y el ojo del buscador de grupos se queda en el borde del minimapa."
L["WN44_6_TITLE"] = "Correcciones"
L["WN44_6_TEXT"] = "Una placa de nombre en la que haces clic mantiene su nombre amarillo mientras el ratón sigue encima. Una opción oculta el encabezado Todos los objetivos del seguimiento, las opciones tienen una página Todas las ventanas, y lo elegido en los desplegables de estadísticas sigue a los perfiles."
L["WN43_1_TITLE"] = "Minimapa cuadrado"
L["WN43_1_TEXT"] = "Minimapa cuadrado hace el mapa cuadrado, con el metal del borde redondo, y los botones del borde siguen el canto. Está desactivado por defecto, actívalo en las opciones (/fcui), en Minimapa. Mientras Rotar minimapa del juego esté activado, el mapa sigue redondo."
L["WN43_2_TITLE"] = "Minimapa"
L["WN43_2_TEXT"] = "Botón para cerrar el minimapa pone la X de Era en la barra de zona: un clic oculta el mapa y otro lo devuelve. Está desactivado por defecto, actívalo en las opciones, en Minimapa. En el modo edición, la barra de zona ya puede ir bajo el mapa, el reloj está en el sitio de Era, con el marco de Era, y Mayús para arrastrar botones del minimapa se puede desactivar para arrastrar sin más."
L["WN43_3_TITLE"] = "Placas de nombre"
L["WN43_3_TEXT"] = "Los números de salud del juego en nuestras placas pueden ir a la derecha, repartidos o a la izquierda: elígelo en Placas de nombre en las opciones (/fcui). Nuestras placas ya muestran los números que eligen las opciones de información de placas del juego, y el nombre de la placa bajo el ratón se vuelve amarillo, como en Classic Era."
L["WN43_4_TITLE"] = "Cartel de subida de nivel"
L["WN43_4_TEXT"] = "El gran cartel de subida de nivel del juego ahora está oculto, ya que la 1.x no tenía. Para volver a verlo, activa Cartel de subida de nivel en las opciones (/fcui), en Otros."
L["WN43_5_TITLE"] = "Ventanas"
L["WN43_5_TEXT"] = "La ventana de macros y su selector de iconos tienen el aspecto de Era. En la hoja de personaje, los recuadros de atributos tienen el borde gris de Era, cada personaje guarda su propia elección de paneles de atributos, y los subencabezados de la pestaña de estadísticas usan el más y el menos clásicos. Opciones por defecto ahora también activa Barras de tamaño clásico; una línea en el chat dice cómo deshacerlo."
L["WN43_6_TITLE"] = "Correcciones"
L["WN43_6_TEXT"] = "En objetivo y foco con barras de salud gruesas, la sanación entrante llena toda la barra y empieza justo donde acaba la salud. El filtro Mostrar niveles de misión del mapa ya no funciona al revés. Los divisores de la barra 1 siguen difuminados bajo el ratón, la página de un objeto de misión ya no se sale de su pergamino, con los bordes de botón ocultos también desaparece el aro del calendario y la lupa de rastreo queda centrada, y las opciones en gris vuelven a mostrar su descripción."
L["WN42_1_TITLE"] = "Minimapa"
L["WN42_1_TEXT"] = "Los botones de minimapa de otros accesorios, y nuestro botón de opciones, pueden verse, verse al pasar el ratón u ocultarse sin agruparlos: Botones de accesorios, en Minimapa en las opciones (/fcui). El icono de rastreo también es un menú desplegable: visible, al pasar el ratón u oculto. Ocultar la N (norte) quita la N de lo alto del borde del minimapa; está desactivado por defecto, actívalo en Minimapa en las opciones. Con el calendario detrás de día y noche, pasar el ratón por ese icono muestra el calendario en su lugar."
L["WN42_2_TITLE"] = "Chat"
L["WN42_2_TEXT"] = "Las pestañas del chat y el marco de la caja de texto pueden verse, verse al pasar el ratón u ocultarse cada uno: Pestañas del chat y Marco de la caja de texto, en Chat en las opciones (/fcui). Mostrarlos al pasar el ratón, bajo Ocultar botones de chat, devuelve los botones ocultos mientras el ratón está sobre el chat; está desactivado por defecto, actívalo ahí en las opciones."
L["WN42_3_TITLE"] = "Bolsas"
L["WN42_3_TEXT"] = "Las opciones de la barra de bolsas están ahora en la página Bolsas. Ocultar también el arte del llavero, bajo Ocultar arte de la barra de bolsas, quita el arte del llavero con el de las bolsas mientras el llavero no está en la barra; está desactivado por defecto, actívalo en las opciones (/fcui), en Bolsas. Con la barra de bolsas en solo la mochila y plegada, la bolsa de componentes se queda y el llavero vuelve al pasar el ratón. En la bolsa única, pasar el ratón por un botón de bolsa vuelve a iluminar sus ranuras, también las del llavero."
L["WN42_4_TITLE"] = "Fundido al pasar el ratón"
L["WN42_4_TEXT"] = "Todo lo que aparece al pasar el ratón ahora aparece y desaparece con un breve fundido en vez de saltar."
L["WN42_5_TITLE"] = "Correcciones"
L["WN42_5_TEXT"] = "Con las Ventanas de profesión desactivadas, el libro de profesiones ya no muestra un recuadro oscuro más allá de su borde. Cambiar una opción en nuestras páginas de los ajustes del juego ya no pone el borde de nuestra ventana sobre la del juego, y esas páginas llegan hasta su pie; la página de opciones también conserva su posición de desplazamiento. Los menús y submenús reciben el aspecto clásico antes de mostrarse. La ventana de colecciones conserva sus filtros, y con un accesorio que mueve ventanas, el tamaño completo del libro de profesiones funciona y el libro de hechizos ya no salta."
L["WN41_1_TITLE"] = "Una bolsa"
L["WN41_1_TEXT"] = "Activar la fila de ranuras de bolsa en la bolsa única ya no rompe su disposición con un error, y con secciones por tipo de bolsa las ranuras del llavero tienen su propia sección."
L["WN41_2_TITLE"] = "Tecla del libro de hechizos"
L["WN41_2_TEXT"] = "La tecla y el botón del libro de hechizos vuelven a abrir el libro de hechizos en lugar de la última página de profesión o de Colecciones mostrada."
L["WN40_1_TITLE"] = "Ventana de colecciones"
L["WN40_1_TEXT"] = "Monturas, mascotas, juguetes, reliquias y apariencias en una ventana clásica con pestañas laterales, con las vistas de modelo del propio juego, un cuadro de búsqueda y un menú Filtro. Se abre con el botón o la tecla de Colecciones y, con ese microbotón oculto, desde una pestaña Colecciones al pie del libro de hechizos, como una página del libro. Activada por defecto; Ventana de colecciones, en Otros en las opciones (/fcui), la desactiva, y Pestaña de colecciones en Libro de hechizos oculta la pestaña."
L["WN40_2_TITLE"] = "Una barra"
L["WN40_2_TEXT"] = "Con Una barra activada, Solo la barra principal le quita las flechas de página y la barra de latencia y pone el llavero con las bolsas. Activar Una barra ahora también oculta el arte de las bolsas, del micromenú y del llavero, junta los botones de las bolsas y pone el micromenú en la esquina de la pantalla con las bolsas encima. Una barra está desactivada por defecto; actívala en las opciones (/fcui), en Barras de acción, donde Llavero con las bolsas y Bolsas juntas también son casillas propias."
L["WN40_3_TITLE"] = "Ventanas de estilo clásico"
L["WN40_3_TEXT"] = "Marcos de ventana ahora es Ventanas de estilo clásico, en la página Aspecto de las opciones: un interruptor, con una casilla por ventana debajo en una lista desplazable con búsqueda. Mientras está desactivado, las opciones de ventana de las otras páginas se atenúan y su descripción dice qué activar. Activarlo o desactivarlo, o la casilla de una ventana, pide una recarga, ya que una ventana abierta conserva el marco con el que se construyó."
L["WN40_4_TITLE"] = "Modo de edición"
L["WN40_4_TEXT"] = "La barra de tótems tiene en el modo de edición los ajustes de la barra de posturas: orientación, filas, tamaño de icono y separación. Los marcos de foco y de mascota también pueden mostrar sus beneficios arriba, desde sus diálogos del modo de edición, y el marco de foco pequeño muestra sus perjuicios arriba igualmente. La flecha de beneficios es ahora un desplegable en las opciones: visible, al pasar el ratón u oculta."
L["WN40_5_TITLE"] = "Una bolsa"
L["WN40_5_TEXT"] = "Una bolsa puede mostrar secciones por tipo de bolsa o por bolsa, las ranuras del llavero tras las de la última bolsa, en su latón (el botón del llavero abre entonces la bolsa única), y las ranuras de bolsa equipadas. Cada una es una casilla bajo Una bolsa en las opciones (/fcui), en Bolsas, desactivada por defecto; actívala ahí."
L["WN40_6_TITLE"] = "Páginas del libro de hechizos y mapa"
L["WN40_6_TEXT"] = "Profesiones y Colecciones cuentan como páginas del libro de hechizos: su botón sigue pulsado en ellas, su tecla cierra la página y el libro se reabre en la última página mostrada. El mapa del mundo clásico se abre en una ventana a la altura del mapa del juego y mantiene tamaño y posición durante un combate."
L["WN40_7_TITLE"] = "Marcos de unidad y barra de PX"
L["WN40_7_TEXT"] = "Las barras de salud gruesas de los jugadores enemigos muestran su color de clase, activado por defecto (También jugadores enemigos, en Salud con color de clase). Marcos de élite separa Jugadores y PNJ, así cada uno conserva o tematiza su dragón. La descripción de la barra de PX puede decir cuántos PX de descanso quedan: PX de descanso en la descripción de la barra de PX, en Barras de acción, desactivado por defecto; actívalo en las opciones (/fcui)."
L["WN40_8_TITLE"] = "Correcciones"
L["WN40_8_TEXT"] = "Hacer clic derecho en la barra de poder de un marco de unidad vuelve a abrir su menú, los nombres en cirílico se muestran en los marcos de unidad y las placas de nombre, Porcentaje de amenaza desactivado oculta también el número propio del juego, una misión pulsada en un addon de seguimiento abre nuestro registro de misiones, y un botón del minimapa ocultado por su propio addon sigue oculto. El tamaño completo del libro de profesiones es el libro clásico dibujado más grande. Una ventana del juego cuyo estilo clásico está desactivado se deja al juego y a otros addons, sin nada nuestro encima, y la casilla de desbloqueo del mapa se atenúa entonces. Al inspeccionar a un jugador siempre aparecen las pestañas Personaje y JcJ. Opciones por defecto (antes Restablecer opciones) cuenta las barras de tamaño clásico como predeterminadas con nuestra disposición. Pequeñas correcciones en los iconos de control de masas de las placas, el brillo del maná del druida, el cuadro del menú del juego, los menús largos del juego y los cuadros del modo de edición."
L["WN39_1_TITLE"] = "Marcadores del mapa de Era"
L["WN39_1_TEXT"] = "En los mapas de Kalimdor y los Reinos del Este, las capitales vuelven a mostrar la torre gris de Era y los pueblos su casa amarilla, con el nombre del pueblo al pasar el ratón. Activado por defecto; Marcadores de ciudades y pueblos de Era, en Mapa en las opciones (/fcui), lo desactiva."
L["WN39_2_TITLE"] = "Otros accesorios de barras de acción"
L["WN39_2_TEXT"] = "Cuando otro accesorio se queda con las barras de acción, la barra clásica se aparta en lugar de dibujarse debajo. Una ventana lo avisa una vez, y una línea en el chat en cada inicio de sesión hasta que desactives Aviso de barras ocupadas en Mensajes del accesorio en las opciones. Mensajes del accesorio ahora también silencia la nota de bienvenida."
L["WN39_3_TITLE"] = "Destello de daño"
L["WN39_3_TEXT"] = "El marco del jugador ya no destella en rojo la salud que acabas de perder, como en la 1.x. Desactivado por defecto; para recuperarlo, actívalo en las opciones (/fcui): Destello de daño, en Marcos de unidad."
L["WN39_4_TITLE"] = "Accesorios para mover ventanas"
L["WN39_4_TEXT"] = "Dejar las ventanas del juego a otros addons deja de colocar, escalar y bloquear las ventanas propias del juego, para que un accesorio que mueve ventanas pueda encargarse de ellas; las nuestras mantienen su candado. Desactivado por defecto; actívalo en las opciones, en Otros. Una nueva pregunta frecuente explica por qué uno de esos accesorios mueve algunas ventanas y otras no."
L["WN39_5_TITLE"] = "Correcciones"
L["WN39_5_TEXT"] = "La barra de bolsas al pasar el ratón muestra las bolsas mientras el ratón está en cualquier parte de la fila, también entre dos bolsas, y el paso del ratón propio de la bolsa de componentes ya no la oculta fuera de la barra clásica. El mapa clásico abierto en combate toma al instante su tamaño y sitio clásicos, Escape vuelve a funcionar tras una ventana de profesión, y activar o desactivar una barra de acción recoloca la barra clásica al instante."
L["WN38_1_TITLE"] = "Minimapa"
L["WN38_1_TEXT"] = "Tras la última actualización del juego, el botón de rastreo y la barra de zona del minimapa vuelven a mostrar su aspecto 1.x, y el nombre de la zona recupera el tamaño de Era. El juego ya no muestra ahí un indicador de dificultad, así que su elección desaparece de las opciones."
L["WN38_2_TITLE"] = "Correcciones"
L["WN38_2_TEXT"] = "Atacar ya no provoca un error del medidor de daño que nombra a ClassicUI Forever, aunque el medidor de daño esté desactivado, y en combate ya no aparece un error de acción bloqueada sobre la barra de bolsas."
L["WN37_1_TITLE"] = "Opciones en dos paneles"
L["WN37_1_TEXT"] = "Las opciones (/fcui) listan sus páginas a la izquierda, con la búsqueda, y muestran la página a la derecha. Ninguna opción y Restablecer opciones actúan por página o para todas, y Restablecer ventanas devuelve cada ventana a su propio tamaño y sitio."
L["WN37_2_TITLE"] = "Barra de bolsas"
L["WN37_2_TEXT"] = "Elige Barra de bolsas en las opciones (/fcui), en Ventanas de bolsas: oculta, visible solo hasta abrir las bolsas o al pasar el ratón, o solo la mochila, donde una flecha pequeña junto a la mochila, visible mientras el ratón está sobre ella, despliega las bolsas."
L["WN37_3_TITLE"] = "Barra 2 junto a la barra 1"
L["WN37_3_TEXT"] = "Elige Barra 2: a la derecha de la barra 1 en la banda, o a la izquierda, en las opciones (/fcui), en Barra clásica: la barra 2 en su sitio predeterminado continúa los huecos de piedra de la banda junto a la barra 1, con el resto de la banda tras ambas."
L["WN37_4_TITLE"] = "Menú de opciones del libro de hechizos"
L["WN37_4_TEXT"] = "La fila de búsqueda del libro de hechizos tiene un menú de opciones: Ocultar pasivos, Agrupar hechizos similares en desplegables (también se arrastran a las barras en combate) y Mostrar todos los rangos de hechizo. Actívalos ahí, o en las opciones (/fcui) en Libro de hechizos."
L["WN37_5_TITLE"] = "Correcciones"
L["WN37_5_TEXT"] = "Los ataques y órdenes de la mascota se arrastran desde la pestaña de mascota en combate. El libro de hechizos ya no sale volando tras un combate con la ventana de botín abierta, una ventana de profesión abierta en combate muestra sus recuadros, arrastrar el mapa con un addon de mapas conserva el mapa, y el brillo al pasar el ratón sobre una placa de nombre se apaga cuando el ratón se va. Siete preguntas nuevas en las FAQ."
L["WN37_6_TITLE"] = "Ventanas"
L["WN37_6_TEXT"] = "Las ventanas del juego que sostiene un movedor de ventanas se le dejan a él. Una ventana del juego cierra otra solo cuando ambas son del tipo que Era cerraba, las demás se quedan en su sitio mientras una se arrastra o se redimensiona fuera de la fila, y un restablecimiento devuelve una ventana del juego a su hueco."
L["WN36_1_TITLE"] = "Árboles de Legado en paralelo"
L["WN36_1_TEXT"] = "Activa Tres árboles en paralelo en las opciones (/fcui), en Ventana de Legado, para ver a la vez los tres árboles de la ventana de Legado, con un solo Aplicar para todos."
L["WN36_2_TITLE"] = "Los botones del minimapa se pulsan"
L["WN36_2_TEXT"] = "Los botones del accesorio en el minimapa, la bolsa de botones de accesorios y el ojo del buscador de grupo se hunden mientras mantienes el ratón pulsado sobre ellos, como en Era."
L["WN36_3_TITLE"] = "Correcciones"
L["WN36_3_TEXT"] = "Los hechizos canalizados muestran una barra de lanzamiento verde y la barra de respiración vuelve a ser transparente, como en Era. Las pestañas de la ventana del personaje se hunden al pulsarlas, el contador del registro de misiones tiene números blancos y los encabezados de misiones del mapa del mundo siguen dorados. La bolsa de botones de accesorios ya no oscurece los iconos, y los botones entran en ella al momento tras conectarte."
L["WN36_4_TITLE"] = "Botón de Legado"
L["WN36_4_TEXT"] = "El botón de Legado ya no se queda pulsado al cerrar su ventana, y el icono de Legado del minimapa vuelve a abrir su ventana."
L["WN35_1_TITLE"] = "Tres árboles de talentos"
L["WN35_1_TEXT"] = "Activa Tres árboles en paralelo en las opciones (/fcui), en Ventana de talentos, para ver los tres árboles a la vez. Su desplegable Altura elige si cada árbol se desplaza, la ventana crece o las filas se juntan."
L["WN35_2_TITLE"] = "Profesiones en doble panel"
L["WN35_2_TEXT"] = "Activa Doble panel en las opciones (/fcui), en Ventanas de profesión, para una ventana más ancha: las recetas a la izquierda y la receta elegida con sus componentes al lado."
L["WN35_3_TITLE"] = "Bolsa de componentes en la bolsa única"
L["WN35_3_TEXT"] = "Activa Bolsa de componentes en la bolsa única en las opciones (/fcui), en Ventanas de bolsa, y sus casillas se abren con la bolsa única como las de cualquier otra bolsa, primero o al final, teñidas de verde si quieres. Pasa el ratón por el botón de la bolsa de componentes para resaltarlas."
L["WN35_4_TITLE"] = "Pestañas del libro de hechizos"
L["WN35_4_TEXT"] = "Las pestañas del libro de hechizos siguen el orden de Era en todas las clases: las de un mago, Arcano, Fuego, Escarcha."
L["WN35_5_TITLE"] = "Correcciones"
L["WN35_5_TEXT"] = "Los puntos de combo se dibujan sobre el emblema JcJ del objetivo, como en Era. Las placas de nombre ya no provocan errores de Lua en las mazmorras. La tecla social vuelve a abrir la ventana social del addon con la lista de la hermandad desactivada, y las ventanas del addon se alinean con addons que centran las ventanas del juego."
L["WN35_6_TITLE"] = "También en retail"
L["WN35_6_TEXT"] = "La página Quién ya no muestra las pestañas laterales del buscador de grupo, que abren el buscador de WoW Forever."
L["WN34_1_TITLE"] = "Colocación de ventanas"
L["WN34_1_TEXT"] = "Las ventanas del accesorio se abren en una fila tras las ventanas del juego, en el orden en que las abres, y se alinean con los accesorios que mueven las ventanas del juego. Una ventana que hayas movido se queda donde la pusiste. Sin espacio, se cierra la más antigua, nunca en combate."
L["WN34_2_TITLE"] = "Libro de hechizos y talentos"
L["WN34_2_TEXT"] = "La gran ventana de libro de hechizos y talentos del juego se cierra cuando abres una ventana del accesorio que no tiene espacio a su lado, como hace el juego con sus propias ventanas."
L["WN34_3_TITLE"] = "Asa de tamaño"
L["WN34_3_TEXT"] = "Con una ventana desbloqueada, arrastra el asa de su esquina inferior derecha para cambiar su tamaño, o haz clic derecho en el asa para volver a su tamaño por defecto."
L["WN34_4_TITLE"] = "Ojo del buscador de grupo"
L["WN34_4_TEXT"] = "El ojo se coloca y se dimensiona de nuevo en el modo edición del juego, con Ajustar al minimapa y Mostrar sin estar en cola en su cuadro."
L["WN34_5_TITLE"] = "Ocultar casillas bloqueadas"
L["WN34_5_TEXT"] = "Sin autenticador en tu cuenta, activa Ocultar casillas bloqueadas en las opciones (/fcui), en Ventanas de bolsa, y la mochila se reduce a las casillas que puedes usar."
L["WN34_6_TITLE"] = "Mapa y estadísticas"
L["WN34_6_TEXT"] = "Maximizado, el mapa del mundo conserva su aspecto de Era, a escala de la pantalla. La descripción del daño muestra la velocidad de ataque y el daño por segundo de cada mano, como en Era."
L["WN34_7_TITLE"] = "También en Forever"
L["WN34_7_TEXT"] = "El mapa del mundo clásico muestra tus coordenadas y las del cursor en una línea en su pie. La pestaña de mascota muestra las filas de Era: Ataque, Poder de ataque, Daño, Defensa y Armadura."
L["WN33_1_TITLE"] = "Solicitudes de amistad"
L["WN33_1_TEXT"] = "Las pestañas de la página de amigos son Amigos, Aliados recientes y Solicitudes de amistad. Las solicitudes de amistad de Battle.net esperan en su propia pestaña, con su número en el nombre: elige una y pulsa Aceptar o Rechazar. La lista de ignorados está en el desplegable junto a tu nombre de Battle.net."
L["WN33_2_TITLE"] = "Comunidades como botón"
L["WN33_2_TEXT"] = "Desactivado por defecto: activa Comunidades como botón en las opciones (/fcui), en Lista de la hermandad. Comunidades deja entonces la fila de pestañas por un botón redondo en la página de la hermandad, y las cuatro pestañas mantienen su ancho de la 1.x. Sin hermandad, una pestaña de comunidades ocupa el lugar de la de hermandad."
L["WN33_3_TITLE"] = "Aviso de actualización"
L["WN33_3_TEXT"] = "Cuando alguien de tu hermandad o grupo tiene un ClassicUI Forever más nuevo, una línea en el chat te lo dice, con un enlace a CurseForge. Mensajes del accesorio, en Otros en las opciones, lo desactiva junto con las demás líneas del accesorio en el chat."
L["WN33_4_TITLE"] = "Cambios de postura más fluidos"
L["WN33_4_TEXT"] = "El sigilo del pícaro, las formas de druida y otros cambios de postura ya no causan un pequeño tirón, y el seguimiento de misiones ya no salta cuando ocurren."
L["WN33_5_TITLE"] = "Detalles JcJ"
L["WN33_5_TEXT"] = "El panel de detalles de la pestaña JcJ se dispone como el del juego, con piezas de la 1.x: una línea bajo tu rango, el encabezado de las próximas recompensas en un marco de hierro y el icono de la recompensa en una casilla de objeto."
L["WN33_6_TITLE"] = "Pestaña de mascota"
L["WN33_6_TEXT"] = "La pestaña de mascota muestra los puntos de adiestramiento de tu mascota, y su barra de experiencia muestra sus números siempre, como en Era. Invocar a tu mascota con la página de personaje abierta ya no la muestra en tu lugar."
L["WN33_7_TITLE"] = "Correcciones"
L["WN33_7_TEXT"] = "Los botones de postura, mascota y posesión siguen el tema. Las filas de pestañas de las ventanas social y de personaje caben en idiomas largos como el alemán, sin cortar ninguna etiqueta. Las filas de reputación se iluminan bajo el ratón como en Era, y la ventana de botín se abre más allá de tus ventanas abiertas. Las líneas del accesorio en el chat empiezan con su grifo."
L["WN32_1_TITLE"] = "El mapa del mundo de Era"
L["WN32_1_TEXT"] = "El mapa del mundo muestra por defecto el gran marco de mapa de Era, con listas desplegables de continente y zona y Alejar en su cabecera. Cada estilo muestra el mapa a su propio tamaño; cambia su tamaño cuando quieras en Ventanas de ClassicUI Forever (modo edición). Para el mapa pequeño de antes, elige Barra de navegación: ninguna en las opciones (/fcui), en Mapa del mundo."
L["WN32_2_TITLE"] = "Opciones del mapa"
L["WN32_2_TEXT"] = "Un recuadro Opciones del mapa abajo a la derecha del mapa del mundo clásico elige lo que muestra el mapa. Muéstralo siempre, al pasar el ratón o nunca en las opciones, en Mapa del mundo."
L["WN32_3_TITLE"] = "La barra de lanzamiento de Era"
L["WN32_3_TEXT"] = "Las barras de lanzamiento de las placas de nombre toman el aspecto de Era, con el icono del hechizo en la ranura izquierda de la barra. La placa de tu objetivo y la que está bajo el ratón brillan más, y un lanzamiento que no se puede interrumpir conserva su icono bajo el escudo de Era. Para la barra antigua, activa Barra de lanzamiento: icono al lado en las opciones, en Placas de nombre."
L["WN32_4_TITLE"] = "Espacio libre en bolsas"
L["WN32_4_TEXT"] = "El número de espacios libres de la mochila sigue el ajuste del juego para mostrar el espacio libre en bolsas, en Interfaz en las opciones del juego, como en Era: desactivado salvo que lo marques, y nunca se muestra dos veces."
L["WN32_5_TITLE"] = "Correcciones"
L["WN32_5_TEXT"] = "Ocultar bordes de botones también cubre los botones de día y noche y de zoom del minimapa, sin un anillo de más al desactivarlo. En Ventanas de ClassicUI Forever (modo edición), los recuadros de las ventanas cerradas aparecen donde están las ventanas, y Restablecer posición devuelve el mapa del mundo al lugar del juego. Aplicar en la ventana de talentos cabe en su botón. Las instalaciones nuevas abren el registro de misiones en doble panel."
L["WN31_1_TITLE"] = "La ventana de oficio de Era"
L["WN31_1_TEXT"] = "La ventana de oficio toma el tamaño, el arte y la disposición de Era, con un filtro por el tipo de objeto creado y detalles de receta que se desplazan cuando los componentes no caben."
L["WN31_2_TITLE"] = "Libro de profesiones"
L["WN31_2_TEXT"] = "El libro de profesiones va sobre el pergamino del libro de hechizos, con el emblema de cada profesión. Las pestañas junto a la ventana de profesiones aparecen al pasar el ratón; elige siempre visibles u ocultas en las opciones (/fcui), en Libro de profesiones. Para la página con franjas, activa ahí Libro estilo Cataclysm."
L["WN31_3_TITLE"] = "Bolsas y llavero"
L["WN31_3_TEXT"] = "Las bolsas de la barra siguen la orientación y la dirección del modo Edición, así que Vertical las pone en columna. El llavero también puede ir tumbado: marca Horizontal en su diálogo del modo Edición."
L["WN31_4_TITLE"] = "Más del aspecto de Era"
L["WN31_4_TEXT"] = "Los libros y las cartas se abren en la ventana de lectura de Era, cada botón del minimapa lleva el anillo de piedra de Era, y las casillas de texto de las ventanas emergentes y el botón de contactos de la ventana social toman las formas de Era."
L["WN31_5_TITLE"] = "Colores del tema"
L["WN31_5_TEXT"] = "Con un tema personalizado, más arte toma su color, como los bordes de listas y desplazamiento en la mayoría de las ventanas, el mapa del mundo pequeño y el anillo de día y noche del minimapa."
L["WN31_6_TITLE"] = "Opciones"
L["WN31_6_TEXT"] = "Un control Distancia máx. de cámara en las opciones (/fcui), en Otros, deja alejar la cámara hasta 4,0. Solo coincidencias, junto a la búsqueda de opciones, muestra solo las opciones que coinciden."
L["WN31_7_TITLE"] = "Correcciones"
L["WN31_7_TEXT"] = "Despojar ya no cierra tus ventanas abiertas, las bolsas de la barra ya no muestran un borde plateado, y una reinstalación con el diseño clásico ya no devuelve las barras del tamaño del juego. Un nombre cortado en la lista Quién se ve entero al señalarlo, y Entrenar se atenúa para una profesión nueva cuando los dos huecos de profesión están ocupados, como en Era. Las barras de profesión ya no muestran dos verdes, y el botón de amigos junto al chat ya no abre la ventana social del juego."
L["WN31_8_TITLE"] = "También en Forever"
L["WN31_8_TEXT"] = "La ventana del personaje tiene la casilla de munición de Era con su flecha hacia la casilla a distancia, y la ventana Buscar grupo muestra el ojo de Era, que gira mientras estás en la lista. El libro de hechizos abierto en combate desde su pestaña Profesiones ya no se abre desplazado a un lado, el arte de la ventana de Legado ya no se mueve entre sus páginas, y los iconos del libro de profesiones ya no saltan durante una creación. Las barras de la pestaña Habilidades tienen el tamaño y el espaciado de Era, con el borde dorado de Era bajo el ratón."
L["WN31_9_TITLE"] = "Ojo del buscador de grupos e icono de rastreo"
L["WN31_9_TEXT"] = "El icono del buscador de grupos y el ojo de cola del juego son un solo botón: en cola, el ojo ocupa el sitio del icono con el aspecto de Era y gira como el de Era. El icono de rastreo tiene el anillo más grande de Era; para mantener el tamaño anterior, activa Icono de rastreo: del tamaño de los demás botones en las opciones (/fcui), en Minimapa."
L["WN31_10_TITLE"] = "Otros addons en el minimapa"
L["WN31_10_TEXT"] = "Los addons que reúnen los botones del minimapa en una bolsa dejan el ojo del buscador de grupos y los demás iconos del minimapa en el anillo, y el botón de opciones muestra su grifo en su bolsa. El borde cuadrado del minimapa de otro addon ya no aparece alrededor del minimapa redondo."
L["WN30_1_TITLE"] = "Correcciones de las barras de acción"
L["WN30_1_TEXT"] = "Ya no aparecen separadores dorados entre los botones de la barra principal cuando cambia de página, como con Sigilo o las formas de druida, y el borde dorado de una habilidad activada vuelve a verse entero."
L["WN30_2_TITLE"] = "Instructor"
L["WN30_2_TEXT"] = "Entrenar en la ventana clásica del instructor vuelve a aprender la habilidad o receta elegida, y tu dinero debajo se ve con todo su brillo."
L["WN29_1_TITLE"] = "Una ventana de Legado clásica"
L["WN29_1_TEXT"] = "El botón y la tecla de Legado abren una ventana de Legado clásica: el camino de recompensas y los desafíos en las antiguas barras de habilidad, con búsqueda y filtro, y los árboles de Legado en la antigua ventana de talentos. Activada por defecto; desactívala en las opciones (/fcui), en Personaje y hechizos."
L["WN29_2_TITLE"] = "Tus propios diseños siguen siendo tuyos"
L["WN29_2_TEXT"] = "Con el addon desactivado, las barras de acción de tus propios diseños del modo Edición ya no quedan en los sitios de la barra clásica. Los sitios guardados ahí antes se devuelven la próxima vez que pulses Recargar IU en las opciones (/fcui) o escribas /fcui off."
L["WN29_3_TITLE"] = "Correcciones"
L["WN29_3_TEXT"] = "/fcui off vuelve a desactivar el addon. Hacer clic en un miembro de la hermandad en combate abre sus detalles. La ventana de opciones del juego ya no se llena de errores tras un combate, los niveles de misión siguen ocultos con la opción desactivada y la flecha para bajar del chat ya no parpadea."
L["WN29_4_TITLE"] = "Huecos de arma"
L["WN29_4_TEXT"] = "Los huecos de arma de la ventana del personaje quedan centrados sobre dos marcos, sin el marco vacío del hueco a distancia."
L["WN28_1_TITLE"] = "Aliados recientes e Ignorar"
L["WN28_1_TEXT"] = "La pestaña Amigos de la ventana social tiene las pestañas Aliados recientes e Ignorar junto a Amigos. Aliados recientes muestra los jugadores con los que te agrupaste hace poco y tiene una línea de búsqueda; Ignorar muestra los jugadores que ignoras."
L["WN28_2_TITLE"] = "De nuevo la ventana social clásica"
L["WN28_2_TEXT"] = "Tras la última actualización del juego, O y el botón de hermandad abrían la nueva ventana social del juego. Vuelven a abrir la clásica, sus pestañas se alinean y la pestaña de banda ha vuelto."
L["WN28_3_TITLE"] = "Correcciones tras la actualización del juego"
L["WN28_3_TEXT"] = "Los puntos de combo vuelven a mostrar los cinco orbes clásicos. La franja oscura sobre el modelo del personaje y el recuadro oscuro en las páginas de anuncios del buscador de grupo han desaparecido, el botón de ordenar funciona en el modo de una bolsa, y el buscador de grupo ya no salta al abrirlo en combate."
L["WN28_4_TITLE"] = "Ventana de botín y bolsas"
L["WN28_4_TEXT"] = "Con Ventana de botín desactivada, la ventana de botín del juego ya no muestra dos cuadrados blancos en sus esquinas. El botón de ordenar de las bolsas cabe junto al cuadro de búsqueda."
L["WN27_1_TITLE"] = "Menos trabajo en segundo plano"
L["WN27_1_TEXT"] = "Las placas de nombre solo se vuelven a colocar cuando cambia un ajuste de las placas, no con cada ajuste que cambie el juego u otro addon. Las coordenadas del minimapa solo se miden cuando cambian. Nada se ve distinto."
L["WN26_1_TITLE"] ="Colores de clase por marco"
L["WN26_1_TEXT"] = "Salud con color de clase y Recuadro de nombre con color de clase están desactivadas por defecto; actívalas en las opciones (/fcui), en Marcos de unidad. Cada una tiene ahora debajo un desplegable de marcos: Jugador, Objetivo y Foco, así el objetivo puede llevar su color de clase mientras tu propio marco sigue como estaba."
L["WN26_2_TITLE"] = "Color del recuadro de nombre"
L["WN26_2_TEXT"] = "Un nuevo desplegable Color del recuadro de nombre, en Marcos de unidad, elige en qué marcos el recuadro de nombre toma el color del juego para la unidad (azul para un jugador amistoso). Objetivo y Foco están marcados, como en Classic Era; desmarca uno para un recuadro sin color. Jugador está desactivado por defecto; actívalo en las opciones (/fcui) para colorear el tuyo."
L["WN26_3_TITLE"] = "Correcciones"
L["WN26_3_TEXT"] = "Con la barra de salud gruesa sobre el nombre, el recuadro de nombre del marco del jugador ya no se ve detrás de la barra. Al desmarcar el recuadro de nombre con color de clase, el color desaparece del objetivo y del foco al instante."
L["WN25_1_TITLE"] = "Grifos"
L["WN25_1_TEXT"] = "Los grifos se guardan ahora con el diseño del modo de edición, como las piezas propias del juego: cada diseño conserva sus propios lugares para ellos, y Guardar en un diseño predefinido del juego pide un diseño nuevo, que los recibe. Un movimiento sin guardar se descarta al cerrar el modo de edición. El diseño clásico de las opciones los devuelve a los extremos de la barra."
L["WN24_1_TITLE"] = "Bolsas"
L["WN24_1_TEXT"] = "Las bolsas abiertas ya no saltan hacia un lado al equipar un objeto con clic derecho, ni en combate ni fuera de él."
L["WN23_1_TITLE"] = "Temporizadores de golpe"
L["WN23_1_TEXT"] = "Cambiar de arma en combate ya no provoca un error de Lua en cada fotograma en que se muestra la barra de golpe, y el destello al golpear sigue funcionando tras el cambio."
L["WN22_1_TITLE"] = "Profesiones"
L["WN22_1_TEXT"] = "Una profesión se abre en la ventana clásica de habilidades comerciales, y el libro de profesiones es el antiguo y pequeño, en el marco del libro de hechizos. El botón de tamaño junto al de cerrar cambia cualquiera de los dos a la ventana completa del juego."
L["WN22_2_TITLE"] = "Libro de hechizos y talentos"
L["WN22_2_TEXT"] = "Un botón de Libro de hechizos en el micromenú, junto a Personaje, abre el libro de hechizos clásico. La ventana de talentos del juego lleva el marco clásico, y el botón de Talentos la abre siempre en tus talentos."
L["WN22_3_TITLE"] = "Micromenú y minimapa"
L["WN22_3_TEXT"] = "Logros, Guía de aventuras y Vivienda salen del micromenú, pues 1.x no los tenía, y cada uno tiene un icono en el minimapa. Para recuperar un botón, desmárcalo en Ocultar microbotones en las opciones (/fcui)."
L["WN22_4_TITLE"] = "Unión rápida"
L["WN22_4_TEXT"] = "Unión rápida ha dejado la fila de pestañas de la ventana social. Abre Amigos y luego Aliados recientes: la pestaña Unión rápida bajo la lista cambia a ella, y la pestaña Aliados recientes vuelve."
L["WN22_5_TITLE"] = "Rendimiento"
L["WN22_5_TEXT"] = "Los temas de color usan mucha menos CPU: el arte coloreado sigue al del juego solo cuando algo cambia, no en cada fotograma. Los menús de clic derecho de los retratos, las bolsas y las ventanas se abren sin tirones."
L["WN22_6_TITLE"] = "Macros"
L["WN22_6_TEXT"] = "Un hechizo llevado con Mayús-clic del libro de hechizos clásico a una macro entra con su nombre y rango, como desde el libro del juego; antes entraba como un enlace de chat, que una macro no puede lanzar. La ventana de macros tiene las pestañas de Classic Era."
L["WN22_7_TITLE"] = "Macros"
L["WN22_7_TEXT"] = "Un hechizo llevado con Mayús-clic del libro de hechizos clásico a una macro entra con su nombre y rango, como desde el libro del juego; antes entraba como un enlace de chat, que una macro no puede lanzar. Los talentos también entran con su nombre. La ventana de macros tiene las pestañas de Classic Era."
L["WN22_8_TITLE"] = "Menús desplegables"
L["WN22_8_TEXT"] = "Los menús desplegables del juego, como el menú de estado (Disponible, Ausente, Ocupado) y el menú de rastreo del minimapa, tienen ahora el marco de hierro de Classic Era, que contiene sus iconos y flechas."
L["WN22_9_TITLE"] = "Reputación y monedas"
L["WN22_9_TEXT"] = "Ambas pestañas conservan las filas clásicas: espaciado uniforme, los encabezados antiguos, una sola columna de barras. Un grupo de facciones tiene su botón de más o menos con sus facciones sangradas debajo, y el filtro es un pequeño botón de flecha arriba a la derecha."
L["WN22_10_TITLE"] = "Otras correcciones"
L["WN22_10_TEXT"] = "Las pestañas bajo una ventana se quedan en su borde inferior; con algunos tamaños de interfaz subían. Mayús-clic en una profesión deja abierto el libro de hechizos, los números de maná de un druida en sus formas siguen el ajuste Texto de estado del juego, y la pestaña Ayuda muestra solo las preguntas de la versión del juego que juegas."
L["WN22_11_TITLE"] = "Ventanas en Retail"
L["WN22_11_TEXT"] = "La bolsa de componentes queda libre de la barra de latencia, la ventana de personaje no tiene líneas finas alrededor del modelo, la ventana social tiene una sola pestaña Quién, y los bordes de las ventanas quedan como en Forever."
L["WN21_1_TITLE"] = "Lista de hermandad"
L["WN21_1_TEXT"] = "Al hacer clic en un miembro se abren sus notas y opciones con todos los miembros; en hermandades grandes, con muchos no se abría nada. La lista también usa mucha menos CPU mientras está abierta."
L["WN21_2_TITLE"] = "Compartir misiones"
L["WN21_2_TEXT"] = "Compartir misión en el registro de misiones clásico funciona con cualquier misión con una sola pulsación, también justo después de entrar al juego. Solo funcionaba con las misiones de la zona que el mapa del mundo había mostrado por última vez."
L["WN21_3_TITLE"] = "Ventanas"
L["WN21_3_TEXT"] = "Una carta abierta tiene el marco de ventana clásico, como la bandeja de entrada, y el panel lateral de la ventana del personaje ya no muestra una fina línea transparente con algunos tamaños de interfaz."
L["WN20_1_TITLE"] ="Detalles de rango JcJ"
L["WN20_1_TEXT"] = "La pestaña JcJ de la ventana del personaje puede mostrar los detalles de tu rango y las recompensas del siguiente. Haz clic en la flecha de abajo a la derecha de la pestaña para abrir el panel lateral."
L["WN20_2_TITLE"] = "Bolsa de botones de addons"
L["WN20_2_TEXT"] = "Su lugar por defecto está ahora a la izquierda del reloj, lejos del ojo del buscador de grupos, y deja en el minimapa nuestros propios iconos, como Legado. El botón Diseño clásico también devuelve a su sitio los botones del minimapa que hayas movido."
L["WN20_3_TITLE"] = "Otros addons"
L["WN20_3_TEXT"] = "Las partes de ClassicUI Forever que desactivas ya no tocan los marcos del juego, así que los addons que los cambian conservan su aspecto."
L["WN19_1_TITLE"] = "Iconos del minimapa"
L["WN19_1_TEXT"] = "Cualquier botón del micromenú puede ir ahora en el minimapa como icono: márcalo en Botones del micromenú en el minimapa, en las opciones (/fcui). Legado y el buscador de grupos están activados por defecto, así Legado vuelve a tener acceso. Mantén Mayús y arrastra para mover nuestros botones del minimapa por el anillo."
L["WN19_2_TITLE"] = "Seguimiento de misiones"
L["WN19_2_TEXT"] = "El seguimiento de objetivos puede ser el seguimiento de misiones sencillo de Classic Era. Desactivado por defecto; para activarlo, pon Seguimiento de objetivos en el de Classic Era en las opciones (/fcui), en Misiones. Clic en un título para abrir la misión, Mayús-clic para dejar de seguirla, clic derecho para más."
L["WN19_3_TITLE"] = "Ventana de opciones"
L["WN19_3_TEXT"] = "La ventana de opciones es más grande y sus listas largas son ahora desplegables, así hay menos que desplazar."
L["WN19_4_TITLE"] = "Porcentaje de amenaza"
L["WN19_4_TEXT"] = "El porcentaje de amenaza puede mostrarse solo en grupo o mazmorra: activa Solo en grupo o mazmorra en las opciones (/fcui), en Marcos de unidad. Desactivado por defecto."
L["WN19_5_TITLE"] = "Detalles de Classic Era"
L["WN19_5_TEXT"] = "La descripción emergente del botón del menú del juego tiene las descripciones de Classic Era, los menús desplegables usan el marco de hierro de Classic Era y los botones del micromenú ya no se vuelven grises con el menú del juego abierto."
L["WN19_6_TITLE"] = "Correcciones"
L["WN19_6_TEXT"] = "Restablecer opciones mantiene las barras de tamaño clásico, los temas personalizados colorean por completo las pestañas de las opciones, el arte de la barra clásica sigue visible en el diseño ClassicUI Forever, el botón de opciones ya no tapa la lupa de rastreo y, con Minimapa desmarcado, los iconos del minimapa ocultados por otro addon siguen ocultos."
L["WN18_1_TITLE"] = "Profesiones"
L["WN18_1_TEXT"] = "La ventana de profesión ahora puede seguir una receta (sus componentes aparecen en el rastreador de objetivos), filtrar por ranura de equipo y enlazar tu profesión en el chat con el eslabón junto a su título. La tecla de profesiones vuelve a abrir el libro de profesiones."
L["WN18_2_TITLE"] = "Dragones de élite"
L["WN18_2_TEXT"] = "Los enemigos de élite pueden mostrar un dragón dorado alrededor de su nivel en la placa de nombre, y los raros uno plateado: activa Dragones de élite en las opciones (/fcui), en Placas de nombre. Con un tema personalizado, Ignorar el tema en los marcos de élite e Ignorar el tema en los dragones de las placas, en Tema personalizado, mantienen los dragones dorados y plateados. Todo desactivado por defecto."
L["WN18_3_TITLE"] = "Brillo de combate"
L["WN18_3_TEXT"] = "Para quitar el pulso rojo del marco del jugador mientras atacas, activa Ocultar brillo de combate en las opciones (/fcui), en Marcos de unidad. Desactivado por defecto."
L["WN18_4_TITLE"] = "Barras de lanzamiento"
L["WN18_4_TEXT"] = "Los hechizos interrumpidos del objetivo, el foco y las placas de nombre ahora se vuelven rojos y solo dicen Interrumpido, como en Classic Era. Para ver quién interrumpió, activa Nombrar a quien interrumpe en las opciones (/fcui), en Barras de lanzamiento. Las canalizaciones se ven en verde."
L["WN18_5_TITLE"] = "Dificultad de instancia"
L["WN18_5_TEXT"] = "La bandera de dificultad que el juego muestra en el minimapa en mazmorras y bandas ahora está oculta. Para recuperarla, elige visible o al pasar el ratón en Minimapa, en las opciones (/fcui)."
L["WN18_6_TITLE"] = "Diseño clásico"
L["WN18_6_TEXT"] = "La figura de durabilidad ya no queda oculta tras las barras laterales, y los beneficios se colocan en los sitios de Classic Era junto al minimapa. El diseño también ofrece el tamaño de interfaz de Classic Era cuando el tuyo es distinto."
L["WN18_7_TITLE"] = "Aspecto"
L["WN18_7_TEXT"] = "Los menús tienen el fondo negro de Classic Era, y las placas de nombre tienen el tamaño de Classic Era. La parte vacía de las barras de experiencia y reputación está sombreada como en Classic Era; para quitar la sombra, desmarca Barras de experiencia y reputación sombreadas en Barra clásica."
L["WN18_8_TITLE"] = "Correcciones"
L["WN18_8_TEXT"] = "Entrenar funciona con recetas muy abajo en la lista de un instructor. Los botones del chat se quedan en todas las pestañas del chat, y Mayús-clic enlaza un talento en el chat. El mapa del mundo abierto en combate ya no captura clics, y los botones rojos del modo de edición se mantienen enteros al cambiar de tema."
L["WN17_1_TITLE"] = "Errores en placas de nombre"
L["WN17_1_TEXT"] = "Con un tema activo, las placas de nombre clásicas ya no causan mensajes de error."
L["WN17_2_TITLE"] = "Beneficios del objetivo"
L["WN17_2_TEXT"] = "Los beneficios bajo los marcos del objetivo y del foco aparecen ahora en su sitio al cambiar de objetivo, sin el breve salto."
L["WN17_3_TITLE"] = "Mapa del mundo en combate"
L["WN17_3_TEXT"] = "El mapa del mundo clásico abierto en combate se ve ahora igual que fuera de combate."
L["WN16_1_TITLE"] = "Iconos de acción"
L["WN16_1_TEXT"] = "Con un tema activo, los iconos de los botones de acción ya no se oscurecen al azar."
L["WN16_2_TITLE"] = "Brillo de combate"
L["WN16_2_TEXT"] = "Con Barras de salud gruesas sobre el nombre, el brillo rojo de combate y el dorado de descanso rodean ahora todo el marco del jugador en lugar de la barra de salud. Las Barras de salud gruesas están desactivadas por defecto; actívalas en las opciones (/fcui), en Marcos de unidad."
L["WN16_3_TITLE"] = "Placas de nombre"
L["WN16_3_TEXT"] = "Con las placas de nombre clásicas desactivadas, las placas de nombre del juego ya no causan mensajes de error."
L["WN15_1_TITLE"] = "Amenaza"
L["WN15_1_TEXT"] = "El porcentaje de amenaza de Classic Era aparece ahora sobre los marcos del objetivo y del foco en combate. El brillo rojo alrededor de los marcos de unidad queda oculto por defecto; para recuperarlo, desmarca Ocultar brillo de amenaza en las opciones (/fcui), en Marcos de unidad."
L["WN15_2_TITLE"] = "Maná de druida"
L["WN15_2_TEXT"] = "En forma de oso y de felino, los druidas ven ahora su maná en una barra pequeña bajo la barra de ira o de energía."
L["WN15_3_TITLE"] = "Color de salud enemiga"
L["WN15_3_TEXT"] = "Desactivado por defecto. Para usarlo, activa Barras de salud gruesas en las opciones (/fcui), en Marcos de unidad, y elige Según reacción en Salud enemiga: los enemigos neutrales tienen la barra amarilla y los hostiles, roja."
L["WN15_4_TITLE"] = "Texto en inglés"
L["WN15_4_TEXT"] = "Para un juego en otro idioma: los textos propios de este addon pueden mostrarse en inglés, parte por parte. Desactivado por defecto; actívalo en las opciones (/fcui), en Otros, Texto en inglés."
L["WN15_5_TITLE"] = "Lista Quién"
L["WN15_5_TEXT"] = "La flecha de arriba de la última columna de la Lista Quién incluye ahora los filtros de clase, raza y zona del juego. Una búsqueda con uno o dos resultados se queda en la ventana en lugar de ir al chat."
L["WN15_6_TITLE"] = "Color plano"
L["WN15_6_TEXT"] = "Color plano pinta el arte de ventanas y barras en un solo color liso en lugar de metal. Ahora mantiene las líneas finas dentro de las ventanas, alrededor de listas, pies y separadores, salvo que actives también Ocultar bordes internos. Ambos están desactivados por defecto: activa Tema personalizado y luego Color plano en las opciones (/fcui), en Aspecto."
L["WN15_7_TITLE"] = "Temporizadores de golpe"
L["WN15_7_TEXT"] = "Los temporizadores de golpe pueden funcionar ahora sin el destello tras cada golpe: desmarca Destello al golpear en las opciones (/fcui), en Temporizadores de golpe."
L["WN15_8_TITLE"] = "Placas de nombre"
L["WN15_8_TEXT"] = "Los nombres y números pequeños de las placas de nombre usan ahora el texto sencillo de Classic Era. Nuevo y desactivado por defecto: Mismo tamaño cerca y lejos mantiene todas las placas del mismo tamaño, como en Classic Era; actívalo en las opciones (/fcui), en Placas de nombre."
L["WN15_9_TITLE"] = "Ventanas"
L["WN15_9_TEXT"] = "Las ventanas de misión, de diálogo y del vendedor y la lista del registro de misiones tienen ahora el borde fino de Classic Era alrededor de su contenido, y la ventana del personaje muestra la cara de tu personaje en todas las pestañas."
L["WN15_10_TITLE"] = "Correcciones"
L["WN15_10_TEXT"] = "Con un tema activo, los bordes de iconos, los anillos de retrato, los menús y las flechas de página del vendedor toman su color, y los controles deslizantes siguen visibles. Las pestañas de la ventana del personaje responden ahora donde se dibujan."
L["WN14_1_TITLE"] = "Mando"
L["WN14_1_TEXT"] = "Con la interfaz de mando activa, el libro de hechizos clásico, los talentos y el registro de misiones se abren dentro de las ventanas del propio juego, para que un mando pueda moverse por ellos."
L["WN14_2_TITLE"] = "Tema en todo"
L["WN14_2_TEXT"] = "Con un tema activo, las piezas del propio juego también toman su color donde dejaste desactivadas las clásicas: minimapa, marcos de unidad, barras, ventanas y los botones del menú del juego."
L["WN14_3_TITLE"] = "Oscuridad"
L["WN14_3_TEXT"] = "Oscuro tiene un deslizador de gris claro a negro, con un botón para volver al valor predeterminado."
L["WN14_4_TITLE"] = "Color plano"
L["WN14_4_TEXT"] = "Color plano (Tema personalizado) muestra las partes que marques en un solo color plano, con las mismas formas."
L["WN14_5_TITLE"] = "Microbotones"
L["WN14_5_TEXT"] = "Ocultar microbotones ahora funciona en el micromenú del propio juego con la barra clásica desactivada, y puede ocultar la tienda."
L["WN14_6_TITLE"] = "Barras 6 a 8"
L["WN14_6_TEXT"] = "Ocultar barras 6 a 8 ya no existe: deciden los ajustes de barras de acción del propio juego."
L["WN14_7_TITLE"] = "Correcciones"
L["WN14_7_TEXT"] = "Coordenadas: ocultas y al pasar el ratón funcionan con el minimapa del juego, los botones de minimapa de otros accesorios toman el tema, y la mochila de un cazador muestra las casillas libres en lugar de la munición."
L["WN13_1_TITLE"] = "Brillo de amenaza"
L["WN13_1_TEXT"] = "Ocultar brillo de amenaza (Marcos de unidad) quita el brillo rojo de amenaza de los marcos de unidad. El número de amenaza del juego se mantiene."
L["WN13_2_TITLE"] = "Objetos de misión"
L["WN13_2_TEXT"] = "Objetos de misión sencillos (Ventanas de bolsa) muestra los objetos de misión de las bolsas y el banco sin el borde de misión."
L["WN13_3_TITLE"] = "Números"
L["WN13_3_TEXT"] = "Números sin separadores (Marcos de unidad) quita los separadores de miles de los números grandes, en las barras y en todo el juego."
L["WN13_4_TITLE"] = "Iconos de acción"
L["WN13_4_TEXT"] = "Con un tema activo, los iconos de acción vuelven a verse enteros, como en Classic Era; solo su propio borde toma el color del tema."
L["WN13_5_TITLE"] = "Tus barras"
L["WN13_5_TEXT"] = "Si la 0.14.0 cambió tus barras, una línea de chat al entrar te deja devolverlas a como estaban o elegir el aspecto clásico."
L["WN13_6_TITLE"] = "Ventana social"
L["WN13_6_TEXT"] = "Las pestañas Amigos y Banda van en su borde fino como en Classic Era, y la descripción de la pestaña Banda vuelve a verse fuera de una banda."
L["WN13_7_TITLE"] = "Correcciones"
L["WN13_7_TEXT"] = "El botín en el ratón se abre con el primer objeto bajo el cursor, las etiquetas de las pestañas se vuelven blancas al pasar el ratón, y Diseño clásico devuelve el micromenú y las casillas de bolsa clásicos."
L["WN12_1_TITLE"] = "Ventanas"
L["WN12_1_TEXT"] = "Junto al botón de cerrar de cada ventana hay un candado y un reinicio: desbloqueada, la ventana se arrastra por su título. Las ventanas de misión y de diálogo, la ventana social, el buscador de grupos y el libro de profesiones se colocan y se ajustan en Ventanas de ClassicUI Forever."
L["WN12_2_TITLE"] = "Temporizadores de golpe"
L["WN12_2_TEXT"] = "Los temporizadores de golpe del juego con el aspecto de la barra de lanzamiento 1.x, un color por mano y un destello en cada golpe. Los colores y el Grosor del borde se eligen en las opciones."
L["WN12_3_TITLE"] = "Barras de salud gruesas"
L["WN12_3_TEXT"] = "Una barra de salud más alta en los marcos de jugador, objetivo y foco, sobre el nombre o sobre el maná (Marcos de unidad). Recuadro de nombre con color de clase y Tamaño de nombres también son nuevos ahí."
L["WN12_4_TITLE"] = "Grifos"
L["WN12_4_TEXT"] = "Los grifos se arrastran, se ajustan o se ocultan en el modo de edición del juego. Con el ajuste activado se alinean con las barras y vuelven a su sitio."
L["WN12_5_TITLE"] = "Medidor de daño"
L["WN12_5_TEXT"] = "El medidor de daño en el marco 1.x, con botones clásicos y un fondo de mármol o de árbol de talentos que se puede mover."
L["WN12_6_TITLE"] = "Idiomas"
L["WN12_6_TEXT"] = "ClassicUI Forever ya está en alemán, francés, español e italiano."
L["WN12_7_TITLE"] = "Opciones"
L["WN12_7_TEXT"] = "Nuevas pestañas Preguntas y Apoyo, un Color personalizado para el tema y una búsqueda que encuentra un ajuste por más nombres."
L["WN12_8_TITLE"] = "Recursos"
L["WN12_8_TEXT"] = "La visualización personal de recursos en barras 1.x con el antiguo borde de placa de nombre, con el ajuste Separación de barras."
L["WN12_9_TITLE"] = "Barra clásica"
L["WN12_9_TEXT"] = "Casillas de bolsa de tamaño clásico, cualquier microbotón se puede ocultar, el botón de Ayuda vuelve al final del micromenú y La franja sostiene las barras 2 y 3 mantiene esas barras en la franja."
L["WN12_10_TITLE"] = "Minimapa y chat"
L["WN12_10_TEXT"] = "Coordenadas, y un borde y una cabecera que se pueden ocultar en el minimapa, el ojo del buscador de grupos en él cuando su microbotón está oculto, y cada botón del chat se oculta por separado."
L["WN12_11_TITLE"] = "Correcciones"
L["WN12_11_TEXT"] = "Las barras ya no saltan a lo alto de la pantalla tras arrastrarlas en el modo de edición, la barra 1 se mueve con las flechas en el modo de edición, la barra de experiencia ya no sale doble al entrar en combate y las páginas de botín ya no repiten objetos."
L["WN12_12_TITLE"] = "Correcciones menores"
L["WN12_12_TEXT"] = "Los números de mascota y de grupo caben en sus barras, el micromenú ya no salta al arrastrarlo, la barra de latencia conserva su marco y las ayudas de los microbotones salen una vez y con el límite de misiones correcto."
L["WN11_1_TITLE"] = "Chat"
L["WN11_1_TEXT"] = "Ocultar botones de chat permite que el chat quede en el borde de la pantalla, y Barra de desplazamiento del chat mantiene la de WoW Forever (Botones de chat)."
L["WN11_2_TITLE"] = "Niveles de misión"
L["WN11_2_TEXT"] = "Niveles de misión (Misiones) muestra el nivel de cada misión en el mapa, en el seguimiento y en el registro de misiones, en sintonía con el filtro propio del mapa."
L["WN11_3_TITLE"] = "Tema oscuro"
L["WN11_3_TEXT"] = "Los menús de clic derecho, los botones de minimapa de accesorios, los botones de zoom, el reloj y el icono de día y noche toman el tema, y los iconos de acción no muestran borde claro."
L["WN11_4_TITLE"] = "Correcciones"
L["WN11_4_TEXT"] = "Sin nivel de misión duplicado en el seguimiento, sin errores de los menús de clic derecho en mazmorras, y el menú del objetivo se queda en pantalla."
L["WN10_1_TITLE"] = "Minimapa"
L["WN10_1_TEXT"] = "Cada parte del minimapa puede mostrarse, mostrarse solo al pasar el ratón u ocultarse (Minimapa en las opciones), y acercar y alejar se mueven cada uno por el anillo en Ventanas de ClassicUI Forever."
L["WN10_2_TITLE"] = "Micromenú"
L["WN10_2_TEXT"] = "Las descripciones de Classic Era en las descripciones de los microbotones, y Ocultar microbotones quita botones sueltos del menú (Barra clásica)."
L["WN10_3_TITLE"] = "Llavero"
L["WN10_3_TEXT"] = "Se abre aunque no tenga llaves, en su propia ventana, con el arte de Classic Era."
L["WN10_4_TITLE"] = "Nuevas opciones"
L["WN10_4_TEXT"] = "Ocultar barra de actitud (Barra clásica), Tamaño del texto del nombre (Placas de nombre) y Descripción de unidad en las barras (Marcos de unidad)."
L["WN10_5_TITLE"] = "Correcciones"
L["WN10_5_TEXT"] = "Las flechas de desplazamiento se vuelven grises cuando no hay nada que desplazar, el registro de misiones resalta como en Classic Era, Última conexión de la hermandad ordena bien y la ventana de macros se abre junto al libro de hechizos."
L["WN10_6_TITLE"] = "Correcciones menores"
L["WN10_6_TEXT"] = "Las flechas de talentos, la pestaña de hermandad sin hermandad, las flechas de página sobre el mapa, la bolsa de botones de accesorios y avisos de diseño más cortos."
L["WN9_1_TITLE"] = "Mapa del mundo clásico"
L["WN9_1_TEXT"] = "El mapa pequeño de Classic Era, con la lista de misiones del mapa en su propio panel al lado y las recompensas tras el texto de la misión. Barra de navegación del mapa en Mapa de las opciones devuelve el diseño de mapa del juego."
L["WN9_2_TITLE"] = "Nuevas opciones"
L["WN9_2_TEXT"] = "Ocultar botón de misiones del mapa (Mapa), Barras de tamaño clásico (Barra clásica) y Sacudida al interrumpir (Barras de lanzamiento)."
L["WN9_3_TITLE"] = "Estilo clásico"
L["WN9_3_TEXT"] = "Los menús de clic derecho, los desplegables, la ventana social, el buscador de grupos, la lista Quién y la lista de la hermandad siguen a Classic Era; la ventana de opciones toma el aspecto del cliente actual de Classic Era, y la lista de ignorados y el probador el estilo clásico."
L["WN9_4_TITLE"] = "Modo edición"
L["WN9_4_TEXT"] = "El libro de hechizos se puede mover y redimensionar en Ventanas de ClassicUI Forever."
L["WN9_5_TITLE"] = "Barras y seguimiento"
L["WN9_5_TEXT"] = "Las barras 4 y 5 mantienen su sitio en el borde de la pantalla, y el seguimiento de misiones ya no se pone encima de ellas."
L["WN9_6_TITLE"] = "Correcciones"
L["WN9_6_TEXT"] = "Los PNJ neutrales muestran su nivel en lugar de una calavera, y hacer clic en las barras de un marco de unidad vuelve a seleccionar objetivo."
L["WN9_7_TITLE"] = "Ventanas y pestañas"
L["WN9_7_TEXT"] = "Las ventanas de vendedor, correo, cédula de hermandad y tabardo, y muchas otras ventanas y pestañas, se alinean con Classic Era; Escape cierra la ventana de cédula de hermandad."
L["WN8_1_TITLE"] = "Grifos sobre las barras"
L["WN8_1_TEXT"] = "Marca Grifos sobre las barras en Barra clásica de las opciones para dibujar los grifos delante de las barras 2 y 3."
L["WN8_2_TITLE"] = "Ventanas que abren al pulsar"
L["WN8_2_TEXT"] = "Las teclas del libro de hechizos, profesiones, talentos, hermandad y registro de misiones y Escape actúan al pulsar, como las ventanas propias del juego."
L["WN8_3_TITLE"] = "Correcciones"
L["WN8_3_TEXT"] = "Los hechizos se vuelven a arrastrar a la barra de acción 1, el nombre de zona se centra en la barra del minimapa esté donde esté el calendario, y las pestañas y órdenes de mascota del libro de hechizos se ven bien."
L["WN7_1_TITLE"] = "Texto de teclas clásico"
L["WN7_1_TEXT"] = "Los nombres de teclas en los botones de acción tienen el tamaño y el contorno de Classic Era. Tamaño del texto de teclas en Estilo de botones de las opciones los agranda o los reduce."
L["WN7_2_TITLE"] = "Sitios del calendario"
L["WN7_2_TEXT"] = "El calendario es un pequeño cuadrado junto al nombre de zona; ponlo en el anillo o detrás del icono de día y noche en Botón del calendario de las opciones. Marca Calendario en Minimapa de Ventanas de ClassicUI Forever en el modo edición para moverlo o redimensionarlo."
L["WN6_1_TITLE"] = "Botón del calendario"
L["WN6_1_TEXT"] = "El calendario está bajo el icono de día y noche del minimapa. Para ocultarlo, desmarca Botón del calendario en Minimapa de las opciones."
L["WN5_1_TITLE"] = "Correcciones"
L["WN5_1_TEXT"] = "La marca de jugadores nuevos bienvenidos del buscador de grupos se alinea con los iconos de rol. Detalles en el registro de cambios completo."
L["WN4_1_TITLE"] = "Correcciones"
L["WN4_1_TEXT"] = "Las pestañas toman el ratón en la propia pestaña, una profesión lanzada desde el libro de hechizos cierra el libro en combate, y la cabecera de la ventana de botín queda limpia. Detalles en el registro de cambios completo."
L["WN3_1_TITLE"] = "Piezas de la barra clásica"
L["WN3_1_TEXT"] = "Classic no tenía botón de profesiones ni bolsa de componentes, así que el botón de profesiones sale del micromenú (las profesiones se abren desde el libro de hechizos) y la bolsa de componentes es un pequeño botón redondo al pasar el ratón. Las barras 2 y 3 vuelven a caber entre los grifos. Ambas son filas en Barra clásica de las opciones."
L["WN2_1_TITLE"] = "Modo edición de ventanas"
L["WN2_1_TEXT"] = "Marca Ventanas en el modo edición para mover y redimensionar la ficha de personaje, el libro de hechizos, los talentos, el registro de misiones, las profesiones y el mapa."
L["WN2_2_TITLE"] = "Perfiles"
L["WN2_2_TEXT"] = "Una pestaña Perfiles en las opciones guarda ajustes con nombre por personaje."
L["WN2_3_TITLE"] = "Bronce u Oscuro"
L["WN2_3_TEXT"] = "El tema personalizado viene en el bronce de Forever o en un antracita oscuro. Mira la opción Tema personalizado."
L["WN2_4_TITLE"] = "Barra clásica"
L["WN2_4_TEXT"] = "Las barras ya no se reducen por defecto. La barra lleva ahora la barra de latencia, el llavero y la bolsa de componentes como en clásico; cada uno se puede mover en el modo edición u ocultar en Barra clásica de las opciones."
L["WN2_5_TITLE"] = "Botones del minimapa"
L["WN2_5_TEXT"] = "Los botones de minimapa de otros accesorios pueden agruparse tras un botón en el anillo. Mira la opción Agrupar botones de accesorios."
L["WN2_6_TITLE"] = "Opciones"
L["WN2_6_TEXT"] = "Secciones de Misiones y Mapa, y filas nuevas para el marco del mapa, la ventana de botín, las tiradas de botín, ocultar el seguimiento del juego, el botón de profesiones y el texto de teclas."
L["WN2_7_TITLE"] = "Restablecer diseño clásico"
L["WN2_7_TEXT"] = "Devuelve de una vez las ventanas, el seguimiento, los grifos, las piezas de barra y los ajustes de diseño."
